import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { FilterDataAccessor } from 'domain/Filter';
import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  usePageFilterStatus,
} from 'hooks';
import { FilterForm } from 'models/Filters';

import { DrillDownBreadcrumbConfig, DrillDownBreadcrumbResult } from './types';

const EMPTY_VALUES = new Set(['', 'ALL', 'All']);

export function useDrillDownBreadcrumb<TKey extends string>(
  config: DrillDownBreadcrumbConfig<TKey>,
): DrillDownBreadcrumbResult {
  const {
    pageName,
    goldenPathOrder,
    navOrderParam,
    resetEvent,
    hasSpecificValue,
    buildClearPatch,
  } = config;

  const { applied } = usePageFilterApplied(pageName);
  const { defaults, dataFilters } = usePageFilterData(pageName);
  const { isLoading } = usePageFilterStatus(pageName);
  const { updateAllForm, apply } = usePageFilterManagement(pageName);

  const appliedRef = useRef(applied);
  appliedRef.current = applied;

  const defaultsRef = useRef(defaults);
  defaultsRef.current = defaults;

  const rootLabel = String(
    FilterDataAccessor.getInstance().getCountry(dataFilters, applied)?.label ??
      '',
  );

  const [navigationOrder, setNavigationOrder] = useState<TKey[]>(() => {
    const params = new URLSearchParams(globalThis.location.search);
    const raw = params.get(navOrderParam);
    if (raw) {
      return raw
        .split(',')
        .filter((k): k is TKey =>
          (goldenPathOrder as readonly string[]).includes(k),
        );
    }

    return goldenPathOrder.filter((key) => {
      const value = params.get(`filter_${key}`);
      return value !== null && !EMPTY_VALUES.has(value);
    });
  });

  const prevAppliedRef = useRef<FilterForm | undefined>(undefined);

  useEffect(() => {
    const prev = prevAppliedRef.current;
    prevAppliedRef.current = applied;

    if (!prev) {
      const params = new URLSearchParams(globalThis.location.search);
      setNavigationOrder((prevOrder) => {
        const cleaned = prevOrder.filter((key) => {
          if (hasSpecificValue(applied?.[key as keyof typeof applied])) {
            return true;
          }
          const urlValue = params.get(`filter_${key}`);
          return urlValue !== null && !EMPTY_VALUES.has(urlValue);
        });
        return cleaned.length === prevOrder.length ? prevOrder : cleaned;
      });
      return;
    }

    setNavigationOrder((prevOrder) => {
      let order = [...prevOrder];
      let changed = false;

      for (const key of goldenPathOrder) {
        const wasSpecific = hasSpecificValue(prev?.[key]);
        const isSpecific = hasSpecificValue(applied?.[key]);

        if (!wasSpecific && isSpecific && !order.includes(key)) {
          order = [...order, key];
          changed = true;
        } else if (!isSpecific && order.includes(key)) {
          order = order.filter((k) => k !== key);
          changed = true;
        }
      }

      return changed ? order : prevOrder;
    });
  }, [applied, goldenPathOrder, hasSpecificValue]);

  useEffect(() => {
    const handleFilterReset = () => {
      setNavigationOrder([]);
    };

    globalThis.addEventListener(resetEvent, handleFilterReset);
    return () => globalThis.removeEventListener(resetEvent, handleFilterReset);
  }, [resetEvent]);

  const isFirstNavigationMount = useRef(true);

  useEffect(() => {
    if (isFirstNavigationMount.current) {
      isFirstNavigationMount.current = false;
      return;
    }

    const params = new URLSearchParams(globalThis.location.search);
    if (navigationOrder.length > 0) {
      params.set(navOrderParam, navigationOrder.join(','));
    } else {
      params.delete(navOrderParam);
    }

    const queryString = params.toString();
    globalThis.history.replaceState(
      {},
      '',
      queryString ? `?${queryString}` : globalThis.location.pathname,
    );
  }, [navOrderParam, navigationOrder]);

  const { path, pathWithKeys } = useMemo(() => {
    const chips: string[] = [];
    const keyed: { label: string; key: TKey }[] = [];

    for (const key of navigationOrder) {
      const value = applied?.[key as keyof typeof applied];
      if (hasSpecificValue(value)) {
        chips.push(String(value));
        keyed.push({ label: String(value), key });
      }
    }

    return { path: chips, pathWithKeys: keyed };
  }, [applied, hasSpecificValue, navigationOrder]);

  const pathWithKeysRef = useRef(pathWithKeys);
  pathWithKeysRef.current = pathWithKeys;

  const goToStep = useCallback(
    (pathIndex: number) => {
      const chips = pathWithKeysRef.current;

      const keysToKeep = new Set(
        pathIndex >= 0 ? chips.slice(0, pathIndex + 1).map((c) => c.key) : [],
      );
      const keysToClean = goldenPathOrder.filter((key) => !keysToKeep.has(key));

      if (keysToClean.length === 0) return;

      const clearedFilters = buildClearPatch(
        defaultsRef.current,
        keysToClean,
        keysToKeep,
      );

      updateAllForm({ ...appliedRef.current, ...clearedFilters });
      apply();
    },
    [apply, buildClearPatch, goldenPathOrder, updateAllForm],
  );

  return { rootLabel, path, goToStep, isLoading };
}
